                    </text>
                ) : null}
            </g>
            {focused || selected ? (
                <path
                    aria-hidden="true"
                    d={path}
                    fill="none"
                    pointerEvents="none"
                    stroke={theme.palette.primary.main}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={strokeWidth + 4}
                />
            ) : null}
        </>
    )
}

import type { DiagramEdgeKind, DiagramLegendEntryData, DiagramRole } from '../../services/diagrams/diagram_data'
